describe('Particle.removeBehaviour', () => {
  let particle;

  beforeEach(() => {
    particle = new Particle();
  });

  test('should remove the behaviour if it exists in the behaviours array', () => {
    const behaviourToRemove = { id: 'behaviour1', parents: {} };
    const otherBehaviour = { id: 'behaviour2' };

    particle.behaviours = [otherBehaviour, behaviourToRemove, otherBehaviour];

    particle.removeBehaviour(behaviourToRemove);

    expect(particle.behaviours).toHaveLength(2);
    expect(particle.behaviours).not.toContain(behaviourToRemove);
    expect(behaviourToRemove.parents).toBeNull();
  });

  test('should not modify the behaviours array if the behaviour does not exist', () => {
    const behaviour1 = { id: 'behaviour1' };
    const behaviour2 = { id: 'behaviour2' };
    const nonExistentBehaviour = { id: 'behaviour3' };

    const initialBehaviours = [behaviour1, behaviour2];
    particle.behaviours = [...initialBehaviours];

    particle.removeBehaviour(nonExistentBehaviour);

    expect(particle.behaviours).toEqual(initialBehaviours);
  });

  test('should set parents to null on the removed behaviour', () => {
    const behaviourToRemove = { id: 'behaviour1', parents: { someRef: 'value' } };
    particle.behaviours = [behaviourToRemove];

    particle.removeBehaviour(behaviourToRemove);

    expect(behaviourToRemove.parents).toBeNull();
  });
});

