    dispatcher.addEventListener('test', handler2);

    dispatcher.dispatchEvent('test');

    expect(handler1).toHaveBeenCalled();
    expect(handler2).toHaveBeenCalled();
  });

  it('should not invoke listeners for a different event type', () => {
    const handler = jest.fn();

    dispatcher.addEventListener('eventA', handler);
    dispatcher.dispatchEvent('eventB');

    expect(handler).not.toHaveBeenCalled();
  });
});

