describe('Proton.removeEmitter', () => {
  let proton;
  let emitter;

  beforeEach(() => {
    proton = new Proton();
    emitter = new Emitter();
  });

  test('should remove the emitter from the emitters array', () => {
    proton.emitters.push(emitter);
    expect(proton.emitters).toHaveLength(1);

    proton.removeEmitter(emitter);

    expect(proton.emitters).toHaveLength(0);
  });

  test('should not remove anything if the emitter is not in the array', () => {
    proton.emitters.push(new Emitter());
    const initialLength = proton.emitters.length;

    proton.removeEmitter(emitter);

    expect(proton.emitters).toHaveLength(initialLength);
    expect(proton.emitters).not.toContain(emitter);
  });

  test('should set the parent property of the emitter to null', () => {
    proton.emitters.push(emitter);
    emitter.parent = proton;

    proton.removeEmitter(emitter);

    expect(emitter.parent).toBeNull();
  });

  test('should dispatch the EMITTER_REMOVED event', () => {
    proton.emitters.push(emitter);
    const handler = jest.fn();
    proton.addEventListener(Proton.EMITTER_REMOVED, handler);

    proton.removeEmitter(emitter);

    expect(handler).toHaveBeenCalledWith(emitter);
  });
});

