    });
  });
});

const Proton = require('../../../src/core/Proton');

// Mock the dependencies that Proton.js imports internally.
// This prevents "Cannot find module" errors for transitive dependencies.
jest.mock('../integration/Integration');
jest.mock('../Pool');
jest.mock('../Stats');

describe('Proton.update', () => {
  let proton;

  beforeEach(() => {
    jest.useFakeTimers().setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
    proton = new Proton();
    proton.now = 0;
    proton.then = 0;
  });

  afterEach(() => {
    jest.useRealTimers();
    Proton.USE_CLOCK = false;
    Proton.DEFAULT_INTERVAL = 0.0167;
  });

  describe('FPS mode: auto', () => {
    beforeEach(() => {
      proton._fps = 'auto';
    });

    it('should dispatch events and update emitters with default interval when USE_CLOCK is false', () => {
      const updateSpy = jest.spyOn(proton, 'dispatchEvent');
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');

      Proton.USE_CLOCK = false;
      proton.update();

      expect(updateSpy).toHaveBeenCalledWith(Proton.PROTON_UPDATE);
      expect(emittersSpy).toHaveBeenCalledWith(0.0167);
      expect(updateSpy).toHaveBeenCalledWith(Proton.PROTON_UPDATE_AFTER);
    });

    it('should initialize "then" timestamp on first call when USE_CLOCK is true', () => {
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');

      Proton.USE_CLOCK = true;
      proton.then = 0;

      proton.update();

      expect(proton.then).not.toBe(0);
      expect(proton.then).toBeGreaterThan(0);
    });

    it('should calculate elapsed time and update emitters when USE_CLOCK is true', () => {
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');

      Proton.USE_CLOCK = true;

      proton.update();
      jest.setSystemTime(new Date('2024-01-01T00:00:00.100Z'));

      proton.update();

      expect(proton.elapsed).toBe(0.1);
      expect(emittersSpy).toHaveBeenCalledWith(0.1);
    });

    it('should not update emitters if elapsed time is 0 or negative when USE_CLOCK is true', () => {
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');

      Proton.USE_CLOCK = true;
      proton.then = new Date().getTime();

      proton.update();

      expect(proton.elapsed).toBe(0);
      expect(emittersSpy).not.toHaveBeenCalled();
    });

    it('should call amendChangeTabsBug when USE_CLOCK is true', () => {
      const amendSpy = jest.spyOn(proton, 'amendChangeTabsBug');

      Proton.USE_CLOCK = true;
      proton.update();

      expect(amendSpy).toHaveBeenCalled();
    });
  });

  describe('FPS mode: custom value', () => {
    beforeEach(() => {
      proton._fps = 30;
      proton._interval = 1 / 30;
    });

    it('should initialize "then" timestamp on first call', () => {
      proton.then = 0;
      proton.update();
      expect(proton.then).not.toBe(0);
    });

    it('should calculate elapsed time but not update if elapsed < interval', () => {
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');
      const dispatchSpy = jest.spyOn(proton, 'dispatchEvent');

      proton.update();
      const initialThen = proton.then;

      jest.setSystemTime(new Date('2024-01-01T00:00:00.010Z'));
      proton.update();

      expect(proton.elapsed).toBe(0.01);
      expect(proton.elapsed).toBeLessThan(proton._interval);
      expect(dispatchSpy).not.toHaveBeenCalledWith(Proton.PROTON_UPDATE);
      expect(emittersSpy).not.toHaveBeenCalled();
      expect(proton.then).toBe(initialThen);
    });

    it('should update and dispatch events when elapsed > interval', () => {
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');
      const dispatchSpy = jest.spyOn(proton, 'dispatchEvent');

      proton.update();

      jest.setSystemTime(new Date('2024-01-01T00:00:00.050Z'));
      proton.update();

      expect(proton.elapsed).toBe(0.05);
      expect(dispatchSpy).toHaveBeenCalledWith(Proton.PROTON_UPDATE);
      expect(emittersSpy).toHaveBeenCalledWith(proton._interval);
      expect(dispatchSpy).toHaveBeenCalledWith(Proton.PROTON_UPDATE_AFTER);
    });

    it('should adjust "then" time correctly to drift correction (modulo logic)', () => {
      const emittersSpy = jest.spyOn(proton, 'emittersUpdate');
      const interval = proton._interval;

      proton.update();
      const startTime = proton.then;

      const drift = 0.010;
      jest.setSystemTime(new Date('2024-01-01T00:00:00.043333Z'));

      proton.update();

      const expectedThen = proton.now - (drift % interval) * 1000;
      expect(proton.then).toBe(expectedThen);
    });
  });
});
